				t.Errorf("expected SessionPrompt = %q, got %q", expectedPrompt, p.SessionPrompt)
			}
			break
		}
	}

	if !foundCommitted {
		t.Errorf("expected to find committed checkpoint %s, got %d points", cpID, len(points))
	}
}

